package com.rumitx.app.repeaters;
import android.app.*;import android.widget.*;import java.io.*;import java.net.*;import java.security.*;import java.util.*;import javax.crypto.*;import javax.crypto.spec.GCMParameterSpec;import android.security.keystore.*;import org.json.*;
public final class RepeaterDownloads {
 public static void copy(InputStream in,OutputStream out,long limit)throws IOException{if(in==null)throw new IOException("No file stream");byte[] b=new byte[65536];long n=0;int got;while((got=in.read(b))!=-1){if(Thread.currentThread().isInterrupted())throw new IOException("Cancelled");n+=got;if(n>limit)throw new IOException("File exceeds size limit");out.write(b,0,got);}}
 private static HttpURLConnection connection(URL url)throws IOException{if(!url.getProtocol().equals("https"))throw new IOException("HTTPS required");HttpURLConnection c=(HttpURLConnection)url.openConnection();c.setConnectTimeout(15000);c.setReadTimeout(20000);c.setInstanceFollowRedirects(false);return c;}
 public static void mapDialog(FeatureActivity a){LinearLayout body=a.column();body.addView(a.label("Download only map files published in your RumiTX GitHub releases. Maps are not bundled and no mass download service is used.",13));EditText url=new EditText(a);url.setHint("https://github.com/Doug815/RumiTX/releases/download/tag/region.map");body.addView(url);EditText checksum=new EditText(a);checksum.setHint("Optional SHA-256 from release notes");body.addView(checksum);new AlertDialog.Builder(a).setTitle("Offline map download").setView(body).setNegativeButton("Cancel",null).setPositiveButton("Download",(d,w)->a.storage(()->downloadMap(a,url.getText().toString(),checksum.getText().toString()))).show();}
 private static void downloadMap(FeatureActivity a,String address,String expected){new Thread(()->{File tmp=null;try{URL initial=new URL(address.trim());if(!initial.getProtocol().equals("https")||!initial.getHost().equalsIgnoreCase("github.com")||!initial.getPath().startsWith("/Doug815/RumiTX/releases/download/")||!initial.getPath().endsWith(".map"))throw new IOException("Use a RumiTX GitHub release .map URL");if(!expected.trim().isEmpty()&&!expected.trim().matches("[a-fA-F0-9]{64}"))throw new IOException("SHA-256 must contain 64 hexadecimal characters");URL target=initial;HttpURLConnection c=null;for(int i=0;i<6;i++){c=connection(target);int code=c.getResponseCode();if(code>=300&&code<400){String redirect=c.getHeaderField("Location");c.disconnect();if(redirect==null)throw new IOException("Missing redirect");target=new URL(target,redirect);continue;}if(code!=200)throw new IOException("Map HTTP "+code);break;}if(c==null||c.getResponseCode()!=200)throw new IOException("Too many redirects");File folder=new File(android.os.Environment.getExternalStorageDirectory(),"RumiTX/maps");folder.mkdirs();String name=new File(initial.getPath()).getName();File out=new File(folder,name);tmp=new File(folder,name+".partial");MessageDigest hash=MessageDigest.getInstance("SHA-256");try(InputStream in=new DigestInputStream(c.getInputStream(),hash);OutputStream stream=new FileOutputStream(tmp)){copy(in,stream,2L*1024*1024*1024);}finally{c.disconnect();}StringBuilder hex=new StringBuilder();for(byte x:hash.digest())hex.append(String.format(Locale.US,"%02x",x&255));if(!expected.trim().isEmpty()&&!hex.toString().equalsIgnoreCase(expected.trim()))throw new IOException("Map checksum mismatch");org.mapsforge.map.reader.MapFile probe=new org.mapsforge.map.reader.MapFile(tmp);probe.close();if(out.exists())throw new IOException("A map with this name already exists; rename or remove it before downloading");if(!tmp.renameTo(out))throw new IOException("Cannot finalize map download");a.runOnUiThread(()->a.message("Saved offline map to /sdcard/RumiTX/maps/"+name+". Open the map and select it from the USB folder."));}catch(Exception e){if(tmp!=null)tmp.delete();a.runOnUiThread(()->a.message("Map download failed: "+e.getMessage()));}},"RumiTX-map-download").start();}
 private static SecretKey key()throws Exception{KeyStore store=KeyStore.getInstance("AndroidKeyStore");store.load(null);if(!store.containsAlias("RumiTX-repeater-token")){KeyGenerator g=KeyGenerator.getInstance("AES","AndroidKeyStore");g.init(new KeyGenParameterSpec.Builder("RumiTX-repeater-token",KeyProperties.PURPOSE_ENCRYPT|KeyProperties.PURPOSE_DECRYPT).setBlockModes(KeyProperties.BLOCK_MODE_GCM).setEncryptionPaddings(KeyProperties.ENCRYPTION_PADDING_NONE).build());g.generateKey();}return (SecretKey)store.getKey("RumiTX-repeater-token",null);}
 private static void saveToken(FeatureActivity a,String token)throws Exception{Cipher c=Cipher.getInstance("AES/GCM/NoPadding");c.init(Cipher.ENCRYPT_MODE,key());byte[] encrypted=c.doFinal(token.getBytes("UTF-8"));a.getSharedPreferences("repeater-api",0).edit().putString("iv",android.util.Base64.encodeToString(c.getIV(),2)).putString("token",android.util.Base64.encodeToString(encrypted,2)).apply();}
 private static String token(FeatureActivity a){try{android.content.SharedPreferences p=a.getSharedPreferences("repeater-api",0);if(!p.contains("token"))return "";Cipher c=Cipher.getInstance("AES/GCM/NoPadding");c.init(Cipher.DECRYPT_MODE,key(),new GCMParameterSpec(128,android.util.Base64.decode(p.getString("iv",""),2)));return new String(c.doFinal(android.util.Base64.decode(p.getString("token",""),2)),"UTF-8");}catch(Exception e){return "";}}
 public static void stateDialog(FeatureActivity a,RepeaterDatabase db,Runnable refresh){LinearLayout body=a.column();body.addView(a.label("Requires RepeaterBook approval for RumiTX and your personal app-bound rbuapp_ token. Shared app_ tokens are not accepted. No token is embedded. Your GPS coordinates are never sent; nearest filtering runs locally after a state download.",13));EditText state=new EditText(a);state.setHint("State FIPS code, e.g. 17 for Illinois / 55 for Wisconsin");state.setInputType(2);body.addView(state);EditText t=new EditText(a);t.setHint("Personal rbuapp_ token");t.setInputType(129);t.setText(token(a));body.addView(t);EditText agent=new EditText(a);agent.setHint("Exact User-Agent approved by RepeaterBook");agent.setText(a.getSharedPreferences("repeater-api",0).getString("agent",""));body.addView(agent);CheckBox nearby=new CheckBox(a);nearby.setText("Show nearest within 100 km after downloading");body.addView(nearby);new AlertDialog.Builder(a).setTitle("Personal state update").setView(body).setNegativeButton("Cancel",null).setPositiveButton("Download",(d,w)->{String auth=t.getText().toString().trim(),s=state.getText().toString().trim(),ua=agent.getText().toString().trim();if(!auth.startsWith("rbuapp_")||!s.matches("[0-9]{1,2}")||ua.isEmpty()){a.message("Enter your approved personal token, state FIPS code, and approved User-Agent.");return;}if(nearby.isChecked())a.locationFeature();downloadState(a,db,s,auth,ua,()->{refresh.run();if(nearby.isChecked()&&a instanceof RepeaterActivity)((RepeaterActivity)a).nearestAfterDownload();});}).show();}
 private static void downloadState(FeatureActivity a,RepeaterDatabase db,String state,String auth,String agent,Runnable refresh){new Thread(()->{try{saveToken(a,auth);a.getSharedPreferences("repeater-api",0).edit().putString("agent",agent).apply();MessageDigest digest=MessageDigest.getInstance("SHA-256");String cacheKey=android.util.Base64.encodeToString(digest.digest((state+":"+auth).getBytes("UTF-8")),android.util.Base64.URL_SAFE|android.util.Base64.NO_WRAP);File cache=new File(a.getCacheDir(),"repeater-state-"+cacheKey+".json");byte[] response;if(cache.exists()&&System.currentTimeMillis()-cache.lastModified()<86400000){response=read(cache);}else{HttpURLConnection c=connection(new URL("https://www.repeaterbook.com/api/export.php?state_id="+state));c.setRequestProperty("X-RB-App-Token",auth);c.setRequestProperty("User-Agent",agent);try{int code=c.getResponseCode();if(code!=200)throw new IOException("RepeaterBook HTTP "+code+(code==429?". Rate limited; no automatic retries.":". Check app approval and token."));ByteArrayOutputStream bytes=new ByteArrayOutputStream();try(InputStream in=c.getInputStream()){copy(in,bytes,20L*1024*1024);}response=bytes.toByteArray();}finally{c.disconnect();}JSONObject object=new JSONObject(new String(response,"UTF-8"));if(object.optJSONArray("results")==null)throw new IOException("API response has no results array");try(FileOutputStream out=new FileOutputStream(cache)){out.write(response);}}
 JSONObject object=new JSONObject(new String(response,"UTF-8"));JSONArray records=object.getJSONArray("results");int count=0,skipped=0;android.database.sqlite.SQLiteDatabase sql=db.getWritableDatabase();sql.beginTransaction();try{for(int i=0;i<records.length();i++){JSONObject row=records.getJSONObject(i);Map<String,String> values=new HashMap<>();java.util.Iterator<String> keys=row.keys();while(keys.hasNext()){String k=keys.next();if(!row.isNull(k))values.put(k,String.valueOf(row.get(k)));}values.put("source","repeaterbook");try{db.save(RepeaterParser.parse(values));count++;}catch(IllegalArgumentException e){skipped++;}}sql.setTransactionSuccessful();}finally{sql.endTransaction();}final String result=count+" repeaters imported, "+skipped+" skipped. Raw response cached privately for 24 hours.";a.runOnUiThread(()->{a.message(result);refresh.run();});}catch(Exception e){a.runOnUiThread(()->a.message("State download failed: "+e.getMessage()));}},"RumiTX-repeater-download").start();}
 private static byte[] read(File f)throws IOException{try(InputStream in=new FileInputStream(f);ByteArrayOutputStream out=new ByteArrayOutputStream()){copy(in,out,20L*1024*1024);return out.toByteArray();}}
}
